<?php $token = $escape($_SESSION['_token']); ?>
<div class="row g-4"><section class="col-xl-4"><div class="card"><div class="card-header"><h2>Domains</h2></div><div class="list-group list-group-flush"><?php foreach ($zones as $zone): ?><a class="list-group-item list-group-item-action d-flex justify-content-between" href="/zones?id=<?= (int) $zone['id'] ?>"><span><?= $escape($zone['name']) ?></span><span class="badge text-bg-light"><?= $zone['deleted_at'] ? 'Deleted' : ($zone['desired_revision'] ? 'r' . (int) $zone['desired_revision'] : 'Draft') ?></span></a><?php endforeach; ?><?php if (!$zones): ?><div class="empty-state">No domains yet.</div><?php endif; ?></div></div>
<div class="card mt-3"><div class="card-body"><h2>Add a domain</h2><form method="post" action="/zones/create"><input type="hidden" name="_token" value="<?= $token ?>"><?php foreach (['name' => ['Domain', 'example.com'], 'primary_ns' => ['Primary nameserver', 'ns1.example.net'], 'secondary_ns' => ['Second nameserver', 'ns2.example.net'], 'soa_email' => ['SOA mailbox (DNS format)', 'hostmaster.example.com']] as $name => [$label, $placeholder]): ?><label class="form-label small" for="<?= $name ?>"><?= $label ?></label><input class="form-control mb-3" id="<?= $name ?>" name="<?= $name ?>" placeholder="<?= $placeholder ?>" required><?php endforeach; ?><button class="btn btn-primary">Create draft</button></form></div></div></section>
<section class="col-xl-8"><?php if ($selected): ?><div class="card"><div class="card-header"><div><h2><?= $escape($selected['name']) ?></h2><span class="small text-secondary">Draft records · published SOA serial <?= (int) $selected['serial'] ?></span></div></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Owner</th><th>Type</th><th>TTL</th><th>Value</th><th></th></tr></thead><tbody><?php foreach ($records as $r): ?><tr><td><?= $escape($r['owner']) ?></td><td><span class="record-type"><?= $escape($r['type']) ?></span></td><td><?= (int) $r['ttl'] ?></td><td class="record-value"><?= $escape($r['value']) ?></td><td><?php if (!$selected['deleted_at']): ?><form method="post" action="/records/delete"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="zone_id" value="<?= (int) $selected['id'] ?>"><input type="hidden" name="record_id" value="<?= (int) $r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if (!$selected['deleted_at']): ?><div class="card-body"><h3>Add record to draft</h3><form class="row g-2" method="post" action="/records/add"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="zone_id" value="<?= (int) $selected['id'] ?>"><div class="col-md-3"><label class="form-label small">Owner<input class="form-control" name="owner" value="@" required></label></div><div class="col-md-3"><label class="form-label small">Type<select class="form-select" name="type"><?php foreach (Arzoie\Dns\Record::TYPES as $type): ?><option><?= $type ?></option><?php endforeach; ?></select></label></div><div class="col-md-3"><label class="form-label small">TTL<input class="form-control" type="number" name="ttl" min="60" value="300" required></label></div><div class="col-md-12"><label class="form-label small w-100">Value<input class="form-control" name="value" required></label><div class="form-text">MX: 10 mail.example.com · SRV: 10 5 443 service.example.com · CAA: 0 issue letsencrypt.org · TXT: plain text</div></div><div class="col-12"><button class="btn btn-outline-primary">Save draft record</button></div></form><hr><details><summary>Edit an existing draft record</summary><form class="row g-2 mt-2" method="post" action="/records/update"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="zone_id" value="<?= (int) $selected['id'] ?>"><div class="col-12"><label class="form-label w-100">Record<select class="form-select" name="record_id"><?php foreach ($records as $r): ?><option value="<?= (int) $r['id'] ?>"><?= $escape($r['owner'] . ' ' . $r['type'] . ' ' . $r['value']) ?></option><?php endforeach; ?></select></label></div><div class="col-md-4"><label class="form-label w-100">New owner<input class="form-control" name="owner" required></label></div><div class="col-md-4"><label class="form-label w-100">New type<select class="form-select" name="type"><?php foreach (Arzoie\Dns\Record::TYPES as $type): ?><option><?= $type ?></option><?php endforeach; ?></select></label></div><div class="col-md-4"><label class="form-label w-100">New TTL<input class="form-control" name="ttl" type="number" min="60" value="300" required></label></div><div class="col-12"><label class="form-label w-100">New value<input class="form-control" name="value" required></label><button class="btn btn-outline-primary">Update draft record</button></div></form></details><hr><form method="post" action="/zones/publish"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="zone_id" value="<?= (int) $selected['id'] ?>"><button class="btn btn-primary">Sign & publish revision</button><p class="form-text mt-2">Validates the complete zone, signs it, and syncs only members missing this revision.</p></form></div><?php endif; ?></div>
<?php if ($revision): ?><div class="card mt-3"><div class="card-body"><h2>DNSSEC & published revision</h2><p>Revision <?= (int) $revision['id'] ?> · <?= $escape($revision['checksum'] ? 'Signed' : ($revision['operation'] === 'delete' ? 'Deletion' : 'Awaiting signing')) ?></p><p class="small">Signature expiry: <?= $escape($revision['signed_until'] ?? 'Pending') ?></p><pre><?= $escape($revision['ds_records'] ?? 'DS records appear after signing.') ?></pre><p class="small text-secondary">Publish DS at your registrar after every public member serves this signed zone. Signing alone does not establish the parent chain of trust.</p></div></div><?php endif; ?>
<?php if (!$selected['deleted_at']): ?><details class="card mt-3"><summary class="card-body text-danger">Remove domain from the network</summary><div class="card-body pt-0"><p>Remove delegation and parent DS records first where appropriate. A deletion is retained for offline members.</p><form method="post" action="/zones/delete"><input type="hidden" name="_token" value="<?= $token ?>"><input type="hidden" name="zone_id" value="<?= (int) $selected['id'] ?>"><label class="form-label">Type the full domain name<input class="form-control" name="confirm_name" required></label><button class="btn btn-danger">Queue deletion</button></form></div></details><?php endif; ?>
<?php else: ?><div class="card"><div class="empty-state"><h2>Select a domain</h2><p>Manage its records, publish signed revisions, and inspect DNSSEC information.</p></div></div><?php endif; ?></section></div>
